class Solution {
    public long rowsNeeded(long cans) {
        long lo = 1, hi = 200_000_000L;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (mid * (mid + 1) / 2 >= cans) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

